param([string]$ProjectRoot='')
$ErrorActionPreference='Stop'
if(-not $ProjectRoot){$ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))}
$lib=Join-Path $ProjectRoot 'src\desktop-hooks\antigravity-reliable-control\hooks\control-lib.ps1'
if(-not(Test-Path -LiteralPath $lib)){Write-Output 'RED: missing v4 authorization and operation implementation';exit 1}
. $lib
$root=Join-Path $env:LOCALAPPDATA ('Temp\antigravity-v4-policy-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null
$task=Join-Path $root 'task';New-Item -ItemType Directory -Path $task|Out-Null
$env:ANTIGRAVITY_HOOK_POLICY_PATH=Join-Path $root 'policy.json';$env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT=Join-Path $root 'bindings';$env:ANTIGRAVITY_HOOK_PROBE_STATE_ROOT=Join-Path $root 'events'
$env:ANTIGRAVITY_HOOK_BINDING_POLICY_ROOT=''
$results=New-Object Collections.Generic.List[object]
function Case($id,[scriptblock]$body){try{&$body;$results.Add(@{id=$id;status='passed'})}catch{$results.Add(@{id=$id;status='failed'});Write-Host "FAIL $id : $($_.Exception.Message)"}}
function Assert($condition){if(-not $condition){throw 'assertion_failed'}}
function Save($path,$v){[IO.File]::WriteAllText($path,($v|ConvertTo-Json -Depth 30))}
$register=Join-Path $ProjectRoot 'src\scripts\register-desktop-project.ps1'
$bindingScript=Join-Path $ProjectRoot 'src\scripts\new-desktop-session-binding.ps1'
$contractPath=Join-Path $task 'contract.json';$ledgerPath=Join-Path $task 'ledger.json'
$contract=@{schema='antigravity-harness-task-contract-v2';contract_id='task1';status='draft';scope=@{project_root=$task;access='write';allowed_paths=@('out.txt','tests/');denied_paths=@('tests/private.txt')}}
$ledger=@{schema='antigravity-harness-attempt-ledger-v1';project_root=$task;task_id='task1';attempts=@(@{attempt_id='attempt1';status='running'})}
Save $contractPath $contract;Save $ledgerPath $ledger
$payload=@{conversationId='fixture-session';stepIdx=1;workspacePaths=@($task);toolCall=@{name='write_to_file';args=@{TargetFile=(Join-Path $task 'out.txt')}}}|ConvertTo-Json -Depth 10|ConvertFrom-Json
Case 'A-unregistered-observe' {Assert ((Get-AgAuthorization $payload).decision -eq 'allow')}
Case 'B-strict-unavailable' {$r=&$register -ProjectRoot $task -Mode strict -PolicyPath $env:ANTIGRAVITY_HOOK_POLICY_PATH|ConvertFrom-Json;Assert ($r.status -eq 'unavailable');Assert (-not(Test-Path $env:ANTIGRAVITY_HOOK_POLICY_PATH))}
Case 'A-project-opt-in' {$r=&$register -ProjectRoot $task -Mode guarded -PolicyPath $env:ANTIGRAVITY_HOOK_POLICY_PATH|ConvertFrom-Json;Assert ($r.status -eq 'success')}
Case 'A-missing-binding' {Assert ((Get-AgAuthorization $payload).decision -eq 'deny')}
Case 'A-valid-binding' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -TaskRoot $task -ContractPath $contractPath -LedgerPath $ledgerPath -AttemptId attempt1 -Role maker|ConvertFrom-Json;Assert ($r.status -eq 'success');Assert ((Get-AgAuthorization $payload).decision -eq 'allow')}
Case 'A-readonly-contract-registration-denied' {$contract.scope.access='read_only';Save $contractPath $contract;$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'readonly-session' -TaskRoot $task -ContractPath $contractPath -LedgerPath $ledgerPath -AttemptId attempt1 -Role maker|ConvertFrom-Json;Assert ($r.status -eq 'error');$contract.scope.access='write';Save $contractPath $contract}
Case 'B-nested-binding-without-workspace' {$policy=Read-AgJson $env:ANTIGRAVITY_HOOK_POLICY_PATH;$policy.projects[0].project_root=$root;Save $env:ANTIGRAVITY_HOOK_POLICY_PATH $policy;$v=@{conversationId='fixture-session';stepIdx=5;toolCall=@{name='run_command';args=@{Cwd=$root;CommandLine='arbitrary child'}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;Assert ((Get-AgAuthorization $v).decision -eq 'deny');$policy.projects[0].project_root=$task;Save $env:ANTIGRAVITY_HOOK_POLICY_PATH $policy}
$bp=Join-Path $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT ('sessions\'+(Get-AgHash 'fixture-session')+'.json')
Case 'A-contract-tamper' {$contract.scope.allowed_paths+=@('extra');Save $contractPath $contract;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$contract.scope.allowed_paths=@('out.txt','tests/');Save $contractPath $contract}
Case 'A-terminal-attempt' {$ledger.attempts[0].status='passed';Save $ledgerPath $ledger;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$ledger.attempts[0].status='running';Save $ledgerPath $ledger}
Case 'A-cross-task-ledger' {$ledger.task_id='wrong';Save $ledgerPath $ledger;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$ledger.task_id='task1';Save $ledgerPath $ledger}
Case 'A-readonly-role' {$b=Read-AgJson $bp;$b.role='reviewer';Save $bp $b;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$b.role='maker';Save $bp $b}
Case 'A-expired' {$b=Read-AgJson $bp;$expiry=$b.expires_at;$b.expires_at='2000-01-01T00:00:00Z';Save $bp $b;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$b.expires_at=$expiry;Save $bp $b}
Case 'A-role-conflict' {$ledger.attempts[0].role='reviewer';Save $ledgerPath $ledger;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$ledger.attempts[0].Remove('role');Save $ledgerPath $ledger}
Case 'A-out-of-scope' {$old=$payload.toolCall.args.TargetFile;$payload.toolCall.args.TargetFile=Join-Path $root 'outside.txt';Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$payload.toolCall.args.TargetFile=$old}
Case 'A-case-relative-path' {$old=$payload.toolCall.args.TargetFile;$payload.toolCall.args.TargetFile='.\OUT.TXT';Assert ((Get-AgAuthorization $payload).decision -eq 'allow');$payload.toolCall.args.TargetFile=$old}
Case 'A-ads' {$old=$payload.toolCall.args.TargetFile;$payload.toolCall.args.TargetFile=$old+':secret';Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$payload.toolCall.args.TargetFile=$old}
Case 'B-terminal-not-scoped-by-cwd' {$v=@{conversationId='fixture-session';stepIdx=2;workspacePaths=@($root);toolCall=@{name='run_command';args=@{Cwd=$root;CommandLine='arbitrary child process'}}}|ConvertTo-Json -Depth 9|ConvertFrom-Json;Assert ((Get-AgAuthorization $v).decision -eq 'deny')}
Case 'B-control-plane-write' {$old=$payload.toolCall.args.TargetFile;$payload.toolCall.args.TargetFile=$bp;Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$payload.toolCall.args.TargetFile=$old}
Case 'A-hardlink-control-alias' {Assert ((Get-AgAuthorization $payload).decision -eq 'allow');$alias=Join-Path $task 'out.txt';New-Item -ItemType HardLink -Path $alias -Target $contractPath|Out-Null;try{Assert ((Get-AgAuthorization $payload).decision -eq 'deny')}finally{Move-Item -LiteralPath $alias -Destination (Join-Path $root 'retained-hardlink.txt');$copy=Join-Path $task 'contract-copy.tmp';[IO.File]::Copy($contractPath,$copy);[IO.File]::Replace($copy,$contractPath,(Join-Path $root 'retained-original-contract.json'))}}
Case 'A-junction' {$junction=Join-Path $task 'tests';New-Item -ItemType Junction -Path $junction -Target $root|Out-Null;$old=$payload.toolCall.args.TargetFile;$payload.toolCall.args.TargetFile=Join-Path $junction 'escape.txt';Assert ((Get-AgAuthorization $payload).decision -eq 'deny');$payload.toolCall.args.TargetFile=$old}
Case 'A-renew-and-narrow' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -Action Renew -AllowedPaths @('out.txt') -ExpectedRevision 1|ConvertFrom-Json;Assert ($r.status -eq 'success');Assert ($r.revision -eq 2);Assert ((Get-AgAuthorization $payload).decision -eq 'allow')}
Case 'A-revision-conflict' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -Action Renew -ExpectedRevision 1|ConvertFrom-Json;Assert ($r.status -eq 'error')}
Case 'A-no-permission-widening' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -Action Renew -AllowedPaths @('out.txt','tests/')|ConvertFrom-Json;Assert ($r.status -eq 'error')}
Case 'A-revoke' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -Action Revoke|ConvertFrom-Json;Assert ($r.status -eq 'success');Assert ((Get-AgAuthorization $payload).decision -eq 'deny')}
Case 'A-revoked-cannot-renew' {$r=&$bindingScript -StateRoot $env:ANTIGRAVITY_HOOK_BINDING_STATE_ROOT -ConversationId 'fixture-session' -Action Renew|ConvertFrom-Json;Assert ($r.status -eq 'error')}
Case 'C-operation-pre-post-not-attempt-close' {$auth=@{decision='allow';reason_code='observe';binding_status='not_applicable'};$p=Add-AgOperation -InputValue $payload -Phase Pre -Authorization $auth;Assert ($p.status -eq 'unresolved');$post=@{conversationId='fixture-session';stepIdx=1;error=''}|ConvertTo-Json|ConvertFrom-Json;$p=Add-AgOperation -InputValue $post -Phase Post;Assert ($p.status -eq 'completed');Assert ((Read-AgJson $ledgerPath).attempts[0].status -eq 'running')}
Case 'C-duplicate-pre-denied' {$p=Add-AgOperation -InputValue $payload -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};Assert ($p.admission -eq 'deny');$f=Get-ChildItem -LiteralPath $env:ANTIGRAVITY_HOOK_PROBE_STATE_ROOT -Recurse -File -Filter ($p.operation_id+'.json');Assert ((Read-AgJson $f.FullName).callbacks[-1].decision -eq 'deny')}
Case 'C-missing-post-result-unclassified' {$v=@{conversationId='no-result';stepIdx=1;workspacePaths=@();toolCall=@{name='view_file';args=@{}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;$null=Add-AgOperation -InputValue $v -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};$p=Add-AgOperation -InputValue (@{conversationId='no-result';stepIdx=1}|ConvertTo-Json|ConvertFrom-Json) -Phase Post;Assert ($p.status -eq 'unclassified')}
Case 'C-malformed-post-error-unclassified' {foreach($errorValue in @($null,@(),@(''),@{bad='shape'},42)){$id=[guid]::NewGuid().ToString('N');$v=@{conversationId=$id;stepIdx=1;workspacePaths=@();toolCall=@{name='view_file';args=@{}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;$null=Add-AgOperation -InputValue $v -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};$p=Add-AgOperation -InputValue (@{conversationId=$id;stepIdx=1;error=$errorValue}|ConvertTo-Json -Depth 8|ConvertFrom-Json) -Phase Post;Assert ($p.status -eq 'unclassified')}}
Case 'C-orphan-late-pre' {$post=@{conversationId='late';stepIdx=2;error=''}|ConvertTo-Json|ConvertFrom-Json;$p=Add-AgOperation -InputValue $post -Phase Post;Assert ($p.status -eq 'unresolved');$pre=@{conversationId='late';stepIdx=2;workspacePaths=@();toolCall=@{name='view_file';args=@{}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;$p=Add-AgOperation -InputValue $pre -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};Assert ($p.status -eq 'unclassified');Assert ($p.admission -eq 'deny')}
Case 'C-run-output-text-not-proof' {$v=@{conversationId='cmd';stepIdx=1;workspacePaths=@();toolCall=@{name='run_command';args=@{CommandLine='PRIVATE_RAW_COMMAND'}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;$null=Add-AgOperation -InputValue $v -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};$post=@{conversationId='cmd';stepIdx=1;error='';output='The command exited with code 0'}|ConvertTo-Json|ConvertFrom-Json;$p=Add-AgOperation -InputValue $post -Phase Post;Assert ($p.status -eq 'unclassified')}
Case 'C-privacy' {$text=(Get-ChildItem -LiteralPath $env:ANTIGRAVITY_HOOK_PROBE_STATE_ROOT -Recurse -File|ForEach-Object{[IO.File]::ReadAllText($_.FullName)}) -join '';Assert (-not $text.Contains('PRIVATE_RAW_COMMAND'));Assert (-not $text.Contains('fixture-session'))}
Case 'C-invalid-persisted-boolean-visible' {$id='invalid-boolean';$v=@{conversationId=$id;stepIdx=1;workspacePaths=@();toolCall=@{name='view_file';args=@{}}}|ConvertTo-Json -Depth 8|ConvertFrom-Json;$null=Add-AgOperation -InputValue $v -Phase Pre -Authorization @{decision='allow';reason_code='observe';binding_status='not_applicable'};$p=Add-AgOperation -InputValue (@{conversationId=$id;stepIdx=1;error=''}|ConvertTo-Json|ConvertFrom-Json) -Phase Post;$f=Get-ChildItem -LiteralPath $env:ANTIGRAVITY_HOOK_PROBE_STATE_ROOT -Recurse -File -Filter ($p.operation_id+'.json');$r=Read-AgJson $f.FullName;$r.callbacks[1].error_observed='false';Save $f.FullName $r;$audit=&(Join-Path $ProjectRoot 'src\scripts\audit-desktop-hook-session.ps1') -StateRoot $env:ANTIGRAVITY_HOOK_PROBE_STATE_ROOT -ConversationId $id|ConvertFrom-Json;Assert ($audit.status -eq 'warning');Assert ($audit.succeeded_count -eq 0)}
$out=Join-Path $ProjectRoot 'artifacts\v4';New-Item -ItemType Directory -Path $out -Force|Out-Null
$report=@{schema='antigravity-v4-test-result';cases=@($results.ToArray());fixture=$root;created_at=[DateTime]::UtcNow.ToString('o')}
[IO.File]::WriteAllText((Join-Path $out ('policy-'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmssfff')+'.json')),($report|ConvertTo-Json -Depth 8))
$report|ConvertTo-Json -Depth 8 -Compress
if(@($results|Where-Object status -eq 'failed').Count){exit 1}
